cpp.code:
long long gcd(long long a, long long b) {
    while (b) { auto t = a % b; a = b; b = t; }
    return a;
}

java.code:
static long gcd(long a, long b) {
    while (b != 0) { long t = a % b; a = b; b = t; }
    return a;
}

python.code:
def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return abs(a)

go.code:
func gcd(a, b int64) int64 {
    for b != 0 { a, b = b, a%b }
    if a < 0 { return -a }
    return a
}
